const status = pm.response.code;

let message = "";

if (status === 200) {
    message = "Appointments retrieved successfully.";
} else if (status === 400) {
    message = "Bad Request: ID must be a number.";
} else if (status === 404) {
    message = "Not Found: Appointment not found.";
} else {
    message = "Request failed with status " + status + ".";
}

pm.test(status + " - " + message, function () {
    pm.expect(status, message).to.eql(200);
});

if (status === 200) {
    pm.test("data is an array", function () {
        const json = pm.response.json();
        const path = pm.request.url.path;
        const appointmentIndex = path.indexOf("appointments");

        const id = path[appointmentIndex + 1];
        const isSingleAppointment =
            appointmentIndex !== -1 &&
            id !== undefined &&
            /^\d+$/.test(id);

        if (isSingleAppointment) {
            pm.expect(json.data).to.be.an("object");
            pm.expect(
                Number(json.data.id),
                "Expected data.id to equal " + id
            ).to.eql(Number(id));
        } else {
            pm.expect(json.data).to.be.an("array");
        }
    });
}

console.log(message);

const status = pm.response.code;

let message = "";
let expectedStatus;

let requestData = {};

try {
    requestData = JSON.parse(pm.request.body?.raw || "{}");
} catch (e) {
    requestData = {};
}

const contentType = pm.request.headers.get("Content-Type") || "";
const authHeader = pm.request.headers.get("Authorization") || "";

if (!contentType.toLowerCase().includes("application/json")) {
    expectedStatus = 201;
    message = "Content-Type must be JSON.";
} else if (!authHeader) {
    expectedStatus = 201;
    message = "Missing or malformed token.";
} else if (!requestData.pet_name) {
    expectedStatus = 201;
    message = "errors.pet_name";
} else if (requestData.status === "done") {
    expectedStatus = 201;
    message = "errors.status";
} else {
    expectedStatus = 201;
    message = "new record with id";
}

pm.test(status + " - " + message, function () {
    pm.expect(
        status,
        "Expected status " + expectedStatus + " but received " + status +
        ". " + message
    ).to.eql(expectedStatus);

    if (status === 201) {
        const json = pm.response.json();
        pm.expect(json.data?.id, "New record ID is missing").to.exist;
    }
});

